  query: 'query ($boardId: ID!, $statusCol: String!, $confCol: String!, $statusVal: String!, $confVal: String!, $limit: Int!) { boards(ids: [$boardId]) { items_page(query_params: { rules: [{ column_id: $statusCol, compare_value: [$statusVal], operator: contains_text }, { column_id: $confCol, compare_value: [$confVal], operator: contains_text }], operator: and }, limit: $limit) { items { id name column_values { id text value } } } } }',
  variables: {
    boardId: $env.MONDAY_CONTACTS_BOARD_ID,
    statusCol: $env.MONDAY_COL_CONTACT_STATUS,
    confCol: $env.MONDAY_COL_CONTACT_EMAIL_CONFIDENCE,
    statusVal: 'Queued for Outreach',
    confVal: 'High',
    limit: parseInt($env.DAILY_SEND_LIMIT || '15', 10)
  }
}) }}

parameters.jsCode:
const items = (((($json.data || {}).boards || [])[0] || {}).items_page || {}).items || [];
const limit = parseInt($env.DAILY_SEND_LIMIT || '15', 10);

function colVal(item, colId) {
  const c = (item.column_values || []).find(c => c.id === colId);
  return c ? (c.text || '') : '';
}

const leads = items.slice(0, limit).map(it => ({
  contacts_item_id: it.id,
  lead_name: colVal(it, $env.MONDAY_COL_CONTACT_NAME) || it.name,
  email: colVal(it, $env.MONDAY_COL_CONTACT_EMAIL),
  email_confidence: colVal(it, $env.MONDAY_COL_CONTACT_EMAIL_CONFIDENCE),
  company: colVal(it, $env.MONDAY_COL_CONTACT_COMPANY),
  source: colVal(it, $env.MONDAY_COL_CONTACT_SOURCE)
})).filter(l => l.email && l.lead_name);

return leads.map(l => ({ json: l }));

