parameters.jsCode:
// With tool_use forcing, Claude returns a content block of type 'tool_use'
// whose `input` is a typed object matching our compose_email schema.
const blocks = $json.content || [];
const toolBlock = blocks.find(b => b && b.type === 'tool_use' && b.name === 'compose_email');
if (!toolBlock || !toolBlock.input) {
  throw new Error('Claude did not invoke compose_email tool. Stop reason: ' + ($json.stop_reason || 'unknown') + '. Response head: ' + JSON.stringify($json).slice(0, 500));
}
const { subject_line, email_body } = toolBlock.input;
if (!subject_line || !email_body) {
  throw new Error('compose_email tool call missing required fields. Got: ' + JSON.stringify(toolBlock.input).slice(0, 500));
}
// Defense in depth: still strip em/en dashes and any stray bullet markers
const clean = (s) => String(s).replace(/[\u2014\u2013]/g, ' ').replace(/^\s*[-*\u2022]\s+/gm, '');
const lead = $('Claude System Prompt').item.json;
return [{ json: {
  contacts_item_id: lead.contacts_item_id,
  lead_name: lead.lead_name,
  email: lead.email,
  company: lead.company,
  source: lead.source,
  subject_line: clean(subject_line),
  email_body: clean(email_body)
}}];

